import{_ as n,o as l,c as a,a4 as i}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20260127081935739.Dc0Bf2-G.png",p="/assets/image-20260127082551747.eibtnra_.png",e="/assets/image-20260127082810568.BNg0v0pa.png",r="/assets/image-20260127083135238.DsWiGNw1.png",o="/assets/image-20260127083226664.BhvZ_U5a.png",k="/assets/image-20260127083955697.COGD9ptO.png",g="/assets/image-20260127084045279.D8hJf-nV.png",m="/assets/image-20260127084341806.CfuYuHmO.png",c="/assets/image-20260127084445410.DvJ0IQkj.png",d="/assets/image-20260127084519095.nTEiErLp.png",h="/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",O=JSON.parse('{"title":"5分钟教你如何在HarmonyOS中使用skill","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/5分钟教你如何在HarmonyOS中使用skill/5分钟教你如何在HarmonyOS中使用skill.md","filePath":"鸿蒙开发技巧/5分钟教你如何在HarmonyOS中使用skill/5分钟教你如何在HarmonyOS中使用skill.md","lastUpdated":1769475035000,"__rawMarkdown":"# 5分钟教你如何在HarmonyOS中使用skill\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：[https://blog.zbztb.cn/](https://blog.zbztb.cn/)\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## skill\\n\\n​\\t最近的skill也是火了，大家应该都有一种不知道skill就等于落后一个时代的感觉\\n\\n我们这里简单的罗列下skill的概念，让大家有b可装。\\n\\n## What are skills\\n\\nskill 是什么？查看官方的定义\\n\\n![](assets/image-20260127081935739.png)\\n\\n万少这里的理解是：skill 也是**一组规则**，或者**一组提示词**。这个规则和提示词可以对应到我们使用AI编辑器的时候的体验：\\n\\n1. **我们可能会在使用AI编辑器工作之前先定义一些rules-规则。**\\n2. **我们在开始工程做某些工作的时候，会频繁的写不同的提示词。**\\n\\n这里的**规则**可能是这样的：\\n\\n```\\n- 我的工程只能使用V2状态管理管理器\\n- 我的工程只能使用Navigation路由不能使用Router路由\\nxxxx\\n\\n```\\n\\n但是由于AI的记忆性、上下文有限制，用着用着可能就会出现AI编辑器乱写代码，\\n\\n无视规则的情况，那么**万少**之前是这样解决的。\\n\\n每一次和AI对话的时候，我都附带上这个规则文件，如\\n\\n```\\n请遵照这个文件xxx的规范，然后帮我实现xxxx功能。\\n```\\n\\n**虽然弱智，但是有效。**\\n\\n那现在的skill为什么说也是类似规则或者提示词呢，\\n\\n原因是这样的，因为在创建skill的时候，需要明确出什么时候使用skill，\\n\\n![](assets/image-20260127082551747.png)\\n\\n所以当我们制定好了这个 **生成HarmonyOS** 代码的 skill后，\\n\\n相当于每一次在你需要生成 **HarmonyOS** 代码的时候，AI便会自动找到这个skill，\\n\\n自动去沿用这个skill中的一些规则和约束，\\n\\n**从这个过程上来看，skill不就是一组会自动被调用的规则和提示词吗**\\n\\n\\n\\n\\n\\n## skill都有哪些组成\\n\\n![](assets/image-20260127082810568.png)\\n\\n一个skill(一个技能) 可以包含4个文件：\\n\\n1. skill.md : skill的介绍 和 元数据 （ skill.md 必须）\\n2. scripts：可以执行的脚本 （可以留空）\\n3. references：引用和参考的文档 （可以留空）\\n4. assets：放一些模板或者资源（可以留空）\\n\\n---\\n\\n上面的文件中，最重要的是**skill.md** ，\\n\\n因为它直接决定了这个skill该如何使用以及什么时候被使用\\n\\n拿一个pdf处理的skill为例\\n\\nskill.md内容需要包含以下部分\\n\\n![](assets/image-20260127083135238.png)\\n\\n---\\n\\n![](assets/image-20260127083226664.png)\\n\\n\\n\\n## 如何高效使用创建skill\\n\\n考虑到创建skill和编写相关的提示词还是有一点门槛的\\n\\n所在目前在网络上有很多开发者写好的实用的skill\\n\\n因此当你想要使用skill的时候有两个选择：\\n\\n1. 自己编写（可以结合ai帮你写）\\n2. 自己搜索好用的skill\\n\\n> https://skillsmp.com/zh\\n\\n\\n\\n\\n\\n这里先推荐一个skill：**skill-creator**\\n\\n顾名思义：**这个skill就是专门帮你创建skill的**\\n\\n你可以先将它下载到你的机子内\\n\\n一般有两种下载方式：\\n\\n1. 全局：任意的地方都可以使用\\n2. 项目：只在你当前项目中使用\\n\\n万少这里是将它设置成了全局使用。\\n\\n> 不同的AI工具有不同的全局skill的设置方法，百度一下即可，不懂也可以联系我\\n\\n\\n\\n然后就可以在你的**HarmonyOS**工程中创建一个专门用来生成鸿蒙代码的**skill**了\\n\\n\\n\\n![](assets/image-20260127083955697.png)\\n\\n最后在当前目录内，我得到了一个专门用来生成**HarmonyOS**代码的**s**kill\\n\\n![](assets/image-20260127084045279.png)\\n\\n**skill.md**的内容一览\\n\\n![](assets/image-20260127084341806.png)\\n\\n> 其中有个小细节，我让它每一次生成HarmonyOS的代码时候都在顶部添加注释： 万少和创建时间\\n>\\n> 当你发现某个新增的文件没有了这个注释：就表示AI偷懒了，此时你可以**疯狂鞭策**它！\\n>\\n\\n---\\n\\n现在可以**测试一下**：\\n\\n![](assets/image-20260127084445410.png)\\n\\n最后得到代码：\\n\\n![](assets/image-20260127084519095.png)\\n\\n\\n\\n## 最后\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)\\n\\n\\n\\n"}'),_={name:"鸿蒙开发技巧/5分钟教你如何在HarmonyOS中使用skill/5分钟教你如何在HarmonyOS中使用skill.md"};function b(u,s,x,A,y,S){return l(),a("div",null,[...s[0]||(s[0]=[i("",64)])])}const E=n(_,[["render",b]]);export{O as __pageData,E as default};
